var SHELL = _global.getCurrentShell();
var language;
var localized_frame = 1;
if(SHELL.getLocalizedFrame != undefined)
{
   localized_frame = SHELL.getLocalizedFrame();
}
switch(localized_frame)
{
   case 1:
      language = "english";
      break;
   case 2:
      language = "portuguese";
      break;
   case 3:
      language = "french";
      break;
   case 4:
      language = "spanish";
      break;
   case 5:
      language = "de";
      break;
   case 6:
      language = "ru";
      break;
   default:
      language = "english";
}
tour.gotoAndStop(language);

